@spec tm_sine_spec  src=tests/specs/tm_sine_spec.lua  loc=230  cases=10
@exercises trackerManager (h.tm), midiManager (h.fm), configManager (h.cm), dataStore (h.ds)
@surface   tm:addEvent, tm:flush, fm:dump, tm:rebuild, tm:getChannel, tm:assignEvent, cm:assign, fm:load, ds:get
@harness   mk

# Intent
  Note macros: sine (continuous pb-augment). Offline park-and-seat: the macro sums onto the
  authored pb base and seats a markerless pb stream on the base lane (no carrier). see design/note-macros-v2.md § Continuous pb

# Helpers
  @fn centsToRaw(cents, pbRange)  @ 13-15
  @fn pbSeatsOf(dump, chan)  @ 20-29
      -- pb-augment seats a summed stream on the base lane (markerless, no carrier). A seat carries a raw
      -- pb `val` (centsToRaw of summed cents + detune) and `shape`. A lone macro seats its own breakpoints;
      -- only a genuine sum densifies. see tm_curve_density_spec
  @fn pbSeatAt(dump, chan, ppq)  @ 31-33
  @fn addVibHost(h, over)  @ 35-41

# Cases
  @case 'sine seats a summed pb stream: rest 0 + depth at the extrema, markerless'  [harness]  @ 48-60
  @case 'sine re-centres the channel at the window end (no residual bend)'  [harness]  @ 66-74
  @case 'seats are confined to the host window; the window opens at centre'  [harness]  @ 80-87
  @case 'G4: sine pb seat stream is byte-identical across flush -> rebuild -> flush (swing + delay)'  [harness]  @ 93-109
  @case 're-deriving the channel keeps its markerless seats markerless (route-by-window fixpoint)'  [harness]  @ 115-135
  @case 'G2: fx present yields pb seats; fx removed leaves none after reconcile'  [harness]  @ 141-151
  @case 'regeneration: a pbRange change rescales pb seat values (cents -> raw at flush)'  [harness]  @ 157-167
  @case 'sine on a higher lane seats a channel pb stream (lane-blind gesture)'  [harness]  @ 173-182
  @case 'noteOff shrink after reload neither parks seats nor restores them as authored pbs'  [harness]  @ 188-214
  @case 'sine seats never surface as a visible cc or pb column'  [harness]  @ 220-227

